//! Content compiled into the binary (used by the WASM build so the game runs
//! fully offline). Generated by `build.rs` from the repository `content/` dir.

use crate::bundle::Source;

include!(concat!(env!("OUT_DIR"), "/embedded_files.rs"));

pub fn sources() -> Vec<Source> {
    EMBEDDED_FILES
        .iter()
        .map(|(p, t)| Source {
            path: (*p).to_string(),
            text: (*t).to_string(),
        })
        .collect()
}
